import { Ionicons } from "@expo/vector-icons";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { useEffect, useState } from "react";
import { ActivityIndicator, Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { firebaseAuth } from "../auth/firebase";
import { createVendorProduct, getCategories, getVendorProducts, updateVendorProduct } from "../catalog/catalog.api";
import { ProductCategorySelect } from "./components/ProductCategorySelect";
import { getVendorWorkspace } from "./vendor.api";

const initial = { name: "", brand: "", categoryId: "", description: "", sku: "", variantTitle: "Default", price: "", compareAt: "", stock: "0" };

export function VendorProductFormScreen({ id }: { id?: string }) {
  const editing = Boolean(id);
  const router = useRouter();
  const user = firebaseAuth?.currentUser ?? null;
  const cache = useQueryClient();
  const products = useQuery({ queryKey: ["vendor", "products"], queryFn: () => getVendorProducts(user!), enabled: Boolean(user && editing) });
  const categories = useQuery({ queryKey: ["catalog", "categories"], queryFn: getCategories });
  const workspace = useQuery({ queryKey: ["vendor", "workspace"], queryFn: () => getVendorWorkspace(user!), enabled: Boolean(user && !editing) });
  const product = products.data?.find((item) => item.id === id);
  const [form, setForm] = useState(initial);
  useEffect(() => { if (product) setForm({ ...initial, name: product.name, brand: product.brand ?? "", categoryId: product.categoryId, description: product.description ?? "", sku: product.variants[0]?.sku ?? "", variantTitle: product.variants[0]?.title ?? "Default", price: product.variants[0] ? String(Number(product.variants[0].price.amountMinor) / 100) : "", compareAt: product.variants[0]?.compareAtPrice ? String(Number(product.variants[0].compareAtPrice.amountMinor) / 100) : "", stock: String(product.variants[0]?.availableQuantity ?? 0) }); }, [product]);
  const valid = form.name.trim().length >= 3 && Boolean(form.categoryId) && (editing || (form.sku.trim().length >= 3 && Number(form.price) > 0));
  const save = useMutation({ mutationFn: () => editing ? updateVendorProduct(user!, id!, { version: product!.version, name: form.name, brand: form.brand.trim() || null, categoryId: form.categoryId, description: form.description.trim() || null }) : createVendorProduct(user!, { shopId: workspace.data!.shops[0]!.id, categoryId: form.categoryId, name: form.name, slug: slug(form.name), brand: form.brand.trim() || null, description: form.description.trim() || null, variants: [{ sku: form.sku, title: form.variantTitle || "Default", priceMinor: minor(form.price), compareAtMinor: form.compareAt ? minor(form.compareAt) : null, currency: "BDT", onHand: Number(form.stock) || 0 }] }), onSuccess: async () => { await cache.invalidateQueries({ queryKey: ["vendor", "products"] }); router.replace("/vendor/products"); } });

  if (editing && products.isLoading) return <Screen title="Loading product"><ActivityIndicator color={colors.primary} /></Screen>;
  if (editing && !product) return <Screen title="Product unavailable" description="This product could not be found in your seller catalog."><Pressable onPress={() => router.replace("/vendor/products")} style={styles.primary}><Text style={styles.primaryText}>Back to products</Text></Pressable></Screen>;
  return <Screen eyebrow="SELLER CATALOG" title={editing ? "Edit product" : "Add a product"} description={editing ? "Update draft or rejected product information before moderation." : "Create a complete draft listing, then submit it for approval."}>
    <View style={styles.steps}><Step active label="Information" number="1" /><View style={styles.rail} /><Step active={!editing} label="Variant" number="2" /><View style={styles.rail} /><Step label="Moderation" number="3" /></View>
    <ModuleCard title="Product information" meta="Use a clear customer-facing name and accurate category."><Field label="Product name *" onChangeText={(name) => setForm({ ...form, name })} placeholder="Enter product name" value={form.name} /><Field label="Brand" onChangeText={(brand) => setForm({ ...form, brand })} placeholder="Brand or manufacturer" value={form.brand} /><ProductCategorySelect categories={categories.data ?? []} onChange={(categoryId) => setForm({ ...form, categoryId })} value={form.categoryId} /><Field label="Description" multiline onChangeText={(description) => setForm({ ...form, description })} placeholder="Describe features, materials, size and usage" value={form.description} /></ModuleCard>
    {!editing ? <ModuleCard title="Default variant" meta="You can manage stock later from the Inventory workspace."><View style={styles.row}><Field label="SKU *" onChangeText={(sku) => setForm({ ...form, sku: sku.toUpperCase() })} placeholder="SKU-001" value={form.sku} /><Field label="Variant title" onChangeText={(variantTitle) => setForm({ ...form, variantTitle })} placeholder="Default" value={form.variantTitle} /></View><View style={styles.row}><Field keyboardType="decimal-pad" label="Selling price (BDT) *" onChangeText={(price) => setForm({ ...form, price })} placeholder="999" value={form.price} /><Field keyboardType="decimal-pad" label="Compare-at price" onChangeText={(compareAt) => setForm({ ...form, compareAt })} placeholder="1299" value={form.compareAt} /><Field keyboardType="numeric" label="Opening stock" onChangeText={(stock) => setForm({ ...form, stock })} placeholder="0" value={form.stock} /></View></ModuleCard> : <ModuleCard title="Variants and stock" meta="Variant pricing and stock stay protected by inventory workflows.">{product?.variants.map((variant) => <View key={variant.id} style={styles.variant}><View style={styles.variantIcon}><Ionicons color={colors.primary} name="pricetag-outline" size={19} /></View><View style={styles.flex}><Text style={styles.variantTitle}>{variant.title}</Text><Text style={styles.variantMeta}>{variant.sku} · ৳{(Number(variant.price.amountMinor) / 100).toLocaleString("en-BD")} · {variant.availableQuantity} available</Text></View></View>)}<Pressable onPress={() => router.push("/vendor/inventory")} style={styles.outline}><Text style={styles.outlineText}>Manage inventory</Text></Pressable></ModuleCard>}
    {save.error ? <Text style={styles.error}>{save.error.message}</Text> : null}<View style={styles.footer}><Pressable onPress={() => router.back()} style={styles.cancel}><Text style={styles.cancelText}>Cancel</Text></Pressable><Pressable disabled={!valid || save.isPending} onPress={() => save.mutate()} style={[styles.primary, (!valid || save.isPending) && styles.disabled]}>{save.isPending ? <ActivityIndicator color={colors.surface} /> : <Text style={styles.primaryText}>{editing ? "Save changes" : "Create draft product"}</Text>}</Pressable></View>
  </Screen>;
}

function Field(props: React.ComponentProps<typeof TextInput> & { label: string }) { const { label, ...input } = props; return <View style={styles.field}><Text style={styles.label}>{label}</Text><TextInput placeholderTextColor={colors.muted} style={[styles.input, input.multiline && styles.multiline]} {...input} /></View>; }
function Step({ active, label, number }: { active?: boolean; label: string; number: string }) { return <View style={styles.step}><View style={[styles.stepNumber, active && styles.stepActive]}><Text style={[styles.stepNumberText, active && styles.stepNumberTextActive]}>{number}</Text></View><Text style={styles.stepLabel}>{label}</Text></View>; }
function slug(value: string) { return value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""); }
function minor(value: string) { return String(Math.round(Number(value) * 100)); }
const styles = StyleSheet.create({ flex: { flex: 1 }, steps: { alignItems: "center", alignSelf: "center", flexDirection: "row", maxWidth: 520, width: "100%" }, step: { alignItems: "center", gap: 5 }, stepNumber: { alignItems: "center", backgroundColor: "#e2e8f0", borderRadius: radius.pill, height: 30, justifyContent: "center", width: 30 }, stepActive: { backgroundColor: colors.primary }, stepNumberText: { color: colors.muted, fontWeight: "900" }, stepNumberTextActive: { color: colors.surface }, stepLabel: { color: colors.muted, fontSize: 9, fontWeight: "800" }, rail: { backgroundColor: colors.border, flex: 1, height: 2, marginBottom: 19 }, field: { flex: 1, gap: 6, minWidth: 180 }, label: { color: colors.text, fontSize: 12, fontWeight: "800" }, input: { backgroundColor: "#f8fafc", borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, minHeight: 48, paddingHorizontal: 13 }, multiline: { minHeight: 130, paddingVertical: 12, textAlignVertical: "top" }, row: { flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, variant: { alignItems: "center", borderBottomColor: colors.border, borderBottomWidth: 1, flexDirection: "row", gap: spacing.sm, paddingVertical: spacing.md }, variantIcon: { alignItems: "center", backgroundColor: colors.primarySoft, borderRadius: radius.md, height: 40, justifyContent: "center", width: 40 }, variantTitle: { color: colors.text, fontWeight: "900" }, variantMeta: { color: colors.muted, fontSize: 10, marginTop: 3 }, outline: { alignItems: "center", borderColor: colors.primary, borderRadius: radius.md, borderWidth: 1, minHeight: 44, justifyContent: "center" }, outlineText: { color: colors.primary, fontWeight: "900" }, footer: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm, justifyContent: "flex-end" }, cancel: { alignItems: "center", borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, justifyContent: "center", minHeight: 48, minWidth: 120 }, cancelText: { color: colors.text, fontWeight: "900" }, primary: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", minHeight: 48, minWidth: 180, paddingHorizontal: spacing.lg }, primaryText: { color: colors.surface, fontWeight: "900" }, disabled: { opacity: .45 }, error: { color: colors.danger } });
